WITH valid_stores AS (SELECT *, DATE_ADD(opened_date, 35) AS opened_date_plus_35d FROM stores WHERE region = 'East'), summary AS (SELECT YEAR(opened_date) AS opened_year, SUM(CASE WHEN city = 'Tokyo' THEN sqft ELSE 0 END) AS tokyo_sqft, COUNT(*) AS store_count FROM valid_stores GROUP BY YEAR(opened_date)) SELECT * FROM summary WHERE store_count < 9 ORDER BY store_count DESC, tokyo_sqft;
